import React from 'react';

interface SpeculationRulesProps {
  basePath?: string;
}

export const InstantNavigationSpeculation: React.FC<SpeculationRulesProps> = ({
  basePath = '/services'
}) => {
  const rules = {
    prerender: [
      {
        where: {
          and: [
            { href_matches: `${basePath}/*` },
            { not: { href_matches: '*/checkout/*' } },
            { not: { selector_matches: '.no-prerender' } }
          ]
        },
        eagerness: 'moderate'
      }
    ],
    prefetch: [
      {
        where: {
          href_matches: '/*'
        },
        eagerness: 'conservative'
      }
    ]
  };

  return (
    <script
      type="speculationrules"
      dangerouslySetInnerHTML={{ __html: JSON.stringify(rules) }}
    />
  );
};

export function executeWhenActivated(callback: () => void): void {
  if (document.prerendering) {
    document.addEventListener(
      'prerenderingchange',
      () => {
        callback();
      },
      { once: true }
    );
  } else {
    callback();
  }
}

// Usage in telemetry or conversion tracking
executeWhenActivated(() => {
  if (window.gtag) {
    window.gtag('event', 'page_view', {
      page_path: window.location.pathname
    });
  }
});
